    const patternWidth = axes.x === "repeat" ? size.width : originWidth;
    const patternHeight = axes.y === "repeat" ? size.height : originHeight;
    return `<pattern id="${id}" patternUnits="userSpaceOnUse" x="${x}" y="${y}" width="${patternWidth}" height="${patternHeight}"><image href="${escaped}" width="${size.width}" height="${size.height}" preserveAspectRatio="none"/></pattern><rect width="${originWidth}" height="${originHeight}" x="${originInset[3]}" y="${originInset[0]}" fill="url(#${id})"/>`;
