  const stopArgs = hasDirection ? args.slice(1) : args;
  const parsedStops = stopArgs.flatMap((stop) => {
    const parsed = parseGradientStopToken(stop);
    if (!parsed) return [];
    const explicit = parsed.explicit.length > 1 ? parsed.explicit : [parsed.explicit[0]];
    return explicit.map(position => ({ ...parsed, explicit: position }));
  });
  const cycle = gradient.repeating
    ? repeatingGradientCycle(parsedStops, gradient.type, direction, width, height)
    : undefined;
  const positions = parsedStops.map(stop => gradientStopPosition(stop.explicit, gradient.type, direction, width, height, cycle));
  for (let index = 0; index < positions.length; index += 1) {
    if (positions[index] != null) continue;
    let left = index - 1;
    while (left >= 0 && positions[left] == null) left -= 1;
    let right = index + 1;
    while (right < positions.length && positions[right] == null) right += 1;
    const start = left >= 0 ? positions[left] : 0;
    const end = right < positions.length ? positions[right] : 1;
    positions[index] = start + (end - start) * ((index - left) / Math.max(1, right - left));
  }
  const stops = parsedStops.map((stop, index) => ({
    ...stop,
    position: Math.max(0, Math.min(1, positions[index] ?? index / Math.max(1, parsedStops.length - 1))),
  }));
