      const fn = raw.match(/^(min|max|clamp)\((.*)\)$/i);
      if (!fn) return undefined;
      const rawEntries = splitCssArguments(fn[2]);
      const validArity = fn[1] === "clamp" ? rawEntries.length === 3 : rawEntries.length >= 2;
      if (!validArity) return undefined;
      const entries = rawEntries.map(entry => resolveExpression(entry));
      if (entries.some(entry => entry === undefined || !Number.isFinite(entry))) return undefined;
      if (fn[1] === "min") return Math.min(...entries);
