    overflowClipMarginBlock: "0px",
    overflowClipMarginBlockStart: "0px",
    overflowClipMarginBlockEnd: "0px",
    overflowClipMarginInline: "0px",
    overflowClipMarginInlineStart: "0px",
    overflowClipMarginInlineEnd: "0px",
